from collections import deque

def candidate(g, bg_conn=4, halo_conn=8, edge_ones_connect=4, include_grid_edge=True):
    R,C=len(g),len(g[0]); out=[r[:] for r in g]
    def nbrs(r,c,conn):
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                if dr==dc==0: continue
                if conn==4 and abs(dr)+abs(dc)!=1: continue
                rr,cc=r+dr,c+dc
                if 0<=rr<R and 0<=cc<C: yield rr,cc
    # comps 1 touching border
    edge_one=set()
    unseen={(r,c) for r in range(R) for c in range(C) if g[r][c]==1}
    while unseen:
        s=unseen.pop(); comp={s}; q=[s]
        while q:
            r,c=q.pop()
            for p in nbrs(r,c,edge_ones_connect):
                if p in unseen and g[p[0]][p[1]]==1:
                    unseen.remove(p);comp.add(p);q.append(p)
        if any(r==0 or c==0 or r==R-1 or c==C-1 for r,c in comp):edge_one|=comp
    # 8-region containing 6 traverse only 8 and seed 6
    seeds=[(r,c) for r in range(R) for c in range(C) if g[r][c]==6]
    seen=set(seeds); q=deque(seeds)
    while q:
        r,c=q.popleft()
        for p in nbrs(r,c,bg_conn):
            rr,cc=p
            if p not in seen and g[rr][cc]==8:
                seen.add(p);q.append(p)
    # output 7 for region cells at outer boundary / adjacent edge 1s
    for r,c in seen:
        if g[r][c]!=8: continue
        cond=include_grid_edge and (r==0 or c==0 or r==R-1 or c==C-1)
        if not cond:
            cond=any(p in edge_one for p in nbrs(r,c,halo_conn))
        if cond:out[r][c]=7
    return out
